def get_hourly_rate(project) -> int:
    """Calculates and rounds up the employee hourly rate within a project.

    Falls back to the project model defaults when a project has no value set.
    """
    annual_employee_cost = project.annual_employee_cost
    if annual_employee_cost is None:
        annual_employee_cost = Project.__table__.c.annual_employee_cost.default.arg

    business_year_hours = project.business_year_hours
    if business_year_hours is None:
        business_year_hours = Project.__table__.c.business_year_hours.default.arg

    return math.ceil(annual_employee_cost / business_year_hours)
